double norm;
adcs_vec3_t delta, diff;
int valid_input = 1;

/* input validation */
if ((gb_input.enable != 0) && (gb_input.enable != 1)) {
    valid_input = 0;
} else if (!isfinite(gb_config.stationary_limit_rad_s) ||
           !isfinite(gb_config.max_sample_delta_rad_s) ||
           !isfinite(gb_config.max_stddev_rad_s) || !isfinite(gb_config.drift_limit_rad_s) ||
           gb_config.stationary_limit_rad_s < 0.0 ||
           gb_config.max_sample_delta_rad_s < 0.0 ||
           gb_config.max_stddev_rad_s < 0.0 || gb_config.drift_limit_rad_s < 0.0) {
    valid_input = 0;
} else if (gb_config.required_samples < 3U || gb_config.required_samples > 100U ||
           gb_config.max_rejected_windows < 1U || gb_config.max_rejected_windows > 20U ||
           gb_config.drift_confirm_samples < 1U || gb_config.drift_confirm_samples > 20U) {
    valid_input = 0;
} else if (gb_input.rate_rad_s == NULL || !adcs_is_finite_vec3(gb_input.rate_rad_s)) {
    valid_input = 0;
}

if (!valid_input) {
    gb_state.mode = GB_FAULT;
    gb_state.count = 0U;
    gb_state.rejected_windows = 0U;
    gb_state.has_previous = 0;
    gb_state.mean_rad_s = (adcs_vec3_t){0.0, 0.0, 0.0};
    gb_state.m2_rad_s2 = (adcs_vec3_t){0.0, 0.0, 0.0};
    gb_state.previous_rate_rad_s = (adcs_vec3_t){0.0, 0.0, 0.0};
    gb_state.bias_rad_s = (adcs_vec3_t){0.0, 0.0, 0.0};
    gb_state.variance_rad_s2 = (adcs_vec3_t){0.0, 0.0, 0.0};
    gb_state.drift_count = 0U;
    gb_output.mode = GB_FAULT;
    gb_output.count = 0U;
    gb_output.rejected_windows = 0U;
    gb_output.rejection = GB_REJECT_NONE;
    gb_output.bias_rad_s = (adcs_vec3_t){0.0, 0.0, 0.0};
    gb_output.variance_rad_s2 = (adcs_vec3_t){0.0, 0.0, 0.0};
    return;
}

if (gb_input.enable == 0) {
    gb_state.mode = GB_OFF;
    gb_state.count = 0U;
    gb_state.rejected_windows = 0U;
    gb_state.has_previous = 0;
    gb_state.mean_rad_s = (adcs_vec3_t){0.0, 0.0, 0.0};
    gb_state.m2_rad_s2 = (adcs_vec3_t){0.0, 0.0, 0.0};
    gb_state.previous_rate_rad_s = (adcs_vec3_t){0.0, 0.0, 0.0};
    gb_state.bias_rad_s = (adcs_vec3_t){0.0, 0.0, 0.0};
    gb_state.variance_rad_s2 = (adcs_vec3_t){0.0, 0.0, 0.0};
    gb_state.drift_count = 0U;
    gb_output.mode = GB_OFF;
    gb_output.count = 0U;
    gb_output.rejected_windows = 0U;
    gb_output.rejection = GB_REJECT_NONE;
    gb_output.bias_rad_s = (adcs_vec3_t){0.0, 0.0, 0.0};
    gb_output.variance_rad_s2 = (adcs_vec3_t){0.0, 0.0, 0.0};
    return;
}

if (gb_state.mode == GB_FAULT) {
    gb_output.mode = GB_FAULT;
    gb_output.count = gb_state.count;
    gb_output.rejected_windows = gb_state.rejected_windows;
    gb_output.rejection = GB_REJECT_NONE;
    gb_output.bias_rad_s = (adcs_vec3_t){0.0, 0.0, 0.0};
    gb_output.variance_rad_s2 = (adcs_vec3_t){0.0, 0.0, 0.0};
    return;
}

if (gb_state.mode == GB_OFF) {
    gb_state.mode = GB_COLLECT;
}

if (gb_state.mode == GB_READY) {
    adcs_vec3_t d;
    d = adcs_vec3_sub(gb_input.rate_rad_s, &gb_state.bias_rad_s);
    if (adcs_vec3_norm(&d) <= gb_config.drift_limit_rad_s) {
        gb_state.drift_count = 0U;
    } else {
        gb_state.drift_count++;
        if (gb_state.drift_count >= gb_config.drift_confirm_samples) {
            gb_state.mode = GB_COLLECT;
            gb_state.count = 0U;
            gb_state.has_previous = 0;
            gb_state.mean_rad_s = (adcs_vec3_t){0.0, 0.0, 0.0};
            gb_state.m2_rad_s2 = (adcs_vec3_t){0.0, 0.0, 0.0};
            gb_state.previous_rate_rad_s = (adcs_vec3_t){0.0, 0.0, 0.0};
            gb_state.bias_rad_s = (adcs_vec3_t){0.0, 0.0, 0.0};
            gb_state.variance_rad_s2 = (adcs_vec3_t){0.0, 0.0, 0.0};
            gb_state.drift_count = 0U;
        }
    }
    if (gb_state.mode == GB_READY) {
        gb_output.mode = GB_READY;
        gb_output.count = gb_state.count;
        gb_output.rejected_windows = gb_state.rejected_windows;
        gb_output.rejection = GB_REJECT_NONE;
        gb_output.bias_rad_s = gb_state.bias_rad_s;
        gb_output.variance_rad_s2 = gb_state.variance_rad_s2;
        return;
    }
}

/* COLLECT */
norm = adcs_vec3_norm(gb_input.rate_rad_s);
if (norm > gb_config.stationary_limit_rad_s) {
    gb_state.count = 0U;
    gb_state.has_previous = 0;
    gb_state.mean_rad_s = (adcs_vec3_t){0.0, 0.0, 0.0};
    gb_state.m2_rad_s2 = (adcs_vec3_t){0.0, 0.0, 0.0};
    gb_state.previous_rate_rad_s = (adcs_vec3_t){0.0, 0.0, 0.0};
    gb_state.rejected_windows++;
    if (gb_state.rejected_windows >= gb_config.max_rejected_windows) {
        gb_state.mode = GB_FAULT;
    }
    gb_output.mode = gb_state.mode;
    gb_output.count = gb_state.count;
    gb_output.rejected_windows = gb_state.rejected_windows;
    gb_output.rejection = GB_REJECT_RATE;
    gb_output.bias_rad_s = (adcs_vec3_t){0.0, 0.0, 0.0};
    gb_output.variance_rad_s2 = (adcs_vec3_t){0.0, 0.0, 0.0};
    return;
}

if (gb_state.has_previous) {
    delta = adcs_vec3_sub(gb_input.rate_rad_s, &gb_state.previous_rate_rad_s);
    if (adcs_vec3_norm(&delta) > gb_config.max_sample_delta_rad_s) {
        gb_state.count = 0U;
        gb_state.has_previous = 0;
        gb_state.mean_rad_s = (adcs_vec3_t){0.0, 0.0, 0.0};
        gb_state.m2_rad_s2 = (adcs_vec3_t){0.0, 0.0, 0.0};
        gb_state.previous_rate_rad_s = (adcs_vec3_t){0.0, 0.0, 0.0};
        gb_state.rejected_windows++;
        if (gb_state.rejected_windows >= gb_config.max_rejected_windows) {
            gb_state.mode = GB_FAULT;
        }
        gb_output.mode = gb_state.mode;
        gb_output.count = gb_state.count;
        gb_output.rejected_windows = gb_state.rejected_windows;
        gb_output.rejection = GB_REJECT_STEP;
        gb_output.bias_rad_s = (adcs_vec3_t){0.0, 0.0, 0.0};
        gb_output.variance_rad_s2 = (adcs_vec3_t){0.0, 0.0, 0.0};
        return;
    }
}

/* accept sample: Welford update */
gb_state.count++;
diff = adcs_vec3_sub(gb_input.rate_rad_s, &gb_state.mean_rad_s);
{
    double scale = 1.0 / (double)gb_state.count;
    gb_state.mean_rad_s.x += diff.x * scale;
    gb_state.mean_rad_s.y += diff.y * scale;
    gb_state.mean_rad_s.z += diff.z * scale;
}
{
    adcs_vec3_t diff2;
    diff2 = adcs_vec3_sub(gb_input.rate_rad_s, &gb_state.mean_rad_s);
    gb_state.m2_rad_s2.x += diff.x * diff2.x;
    gb_state.m2_rad_s2.y += diff.y * diff2.y;
    gb_state.m2_rad_s2.z += diff.z * diff2.z;
}
gb_state.previous_rate_rad_s = *gb_input.rate_rad_s;
gb_state.has_previous = 1;

if (gb_state.count >= gb_config.required_samples) {
    adcs_vec3_t var;
    double varx, vary, varz, lim2;
    varx = gb_state.m2_rad_s2.x / (double)gb_state.count;
    vary = gb_state.m2_rad_s2.y / (double)gb_state.count;
    varz = gb_state.m2_rad_s2.z / (double)gb_state.count;
    lim2 = gb_config.max_stddev_rad_s * gb_config.max_stddev_rad_s;
    if (varx <= lim2 && vary <= lim2 && varz <= lim2) {
        gb_state.bias_rad_s = gb_state.mean_rad_s;
        var = (adcs_vec3_t){varx, vary, varz};
        gb_state.variance_rad_s2 = var;
        gb_state.mode = GB_READY;
        gb_state.drift_count = 0U;
        gb_output.mode = GB_READY;
        gb_output.count = gb_state.count;
        gb_output.rejected_windows = gb_state.rejected_windows;
        gb_output.rejection = GB_REJECT_NONE;
        gb_output.bias_rad_s = gb_state.bias_rad_s;
        gb_output.variance_rad_s2 = gb_state.variance_rad_s2;
        return;
    } else {
        gb_state.count = 0U;
        gb_state.has_previous = 0;
        gb_state.mean_rad_s = (adcs_vec3_t){0.0, 0.0, 0.0};
        gb_state.m2_rad_s2 = (adcs_vec3_t){0.0, 0.0, 0.0};
        gb_state.previous_rate_rad_s = (adcs_vec3_t){0.0, 0.0, 0.0};
        gb_state.rejected_windows++;
        if (gb_state.rejected_windows >= gb_config.max_rejected_windows) {
            gb_state.mode = GB_FAULT;
        }
        gb_output.mode = gb_state.mode;
        gb_output.count = gb_state.count;
        gb_output.rejected_windows = gb_state.rejected_windows;
        gb_output.rejection = GB_REJECT_VARIANCE;
        gb_output.bias_rad_s = (adcs_vec3_t){0.0, 0.0, 0.0};
        gb_output.variance_rad_s2 = (adcs_vec3_t){0.0, 0.0, 0.0};
        return;
    }
}

{
    adcs_vec3_t var;
    var.x = gb_state.m2_rad_s2.x / (double)gb_state.count;
    var.y = gb_state.m2_rad_s2.y / (double)gb_state.count;
    var.z = gb_state.m2_rad_s2.z / (double)gb_state.count;
    gb_output.mode = GB_COLLECT;
    gb_output.count = gb_state.count;
    gb_output.rejected_windows = gb_state.rejected_windows;
    gb_output.rejection = GB_REJECT_NONE;
    gb_output.bias_rad_s = (adcs_vec3_t){0.0, 0.0, 0.0};
    gb_output.variance_rad_s2 = var;
}

