                    double vlim = gb_config.max_stddev_rad_s * gb_config.max_stddev_rad_s;
                    if ((vx <= vlim) && (vy <= vlim) && (vz <= vlim)) {
                        gb_state.bias_rad_s = gb_state.mean_rad_s;
                        gb_state.variance_rad_s2 = (adcs_vec3_t){vx, vy, vz};
                        gb_state.mode = GB_READY;
                        gb_state.drift_count = 0U;
                    } else {
                        gb_state.count = 0U;
                        gb_state.has_previous = 0;
                        gb_state.mean_rad_s = (adcs_vec3_t){0.0, 0.0, 0.0};
                        gb_state.m2_rad_s2 = (adcs_vec3_t){0.0, 0.0, 0.0};
                        gb_state.rejected_windows++;
                        gb_output.rejection = GB_REJECT_VARIANCE;
                        if (gb_state.rejected_windows >= gb_config.max_rejected_windows) {
                            gb_state.mode = GB_FAULT;
                        }
                    }
                }
            }
        }
    }
}

/* ---- 发布输出（门槛外，每次调用都执行） ---- */
gb_output.mode = gb_state.mode;
gb_output.count = gb_state.count;
gb_output.rejected_windows = gb_state.rejected_windows;
if (gb_state.mode == GB_READY) {
    gb_output.bias_rad_s = gb_state.bias_rad_s;
    gb_output.variance_rad_s2 = gb_state.variance_rad_s2;
} else if (gb_state.mode == GB_COLLECT) {
    gb_output.bias_rad_s = (adcs_vec3_t){0.0, 0.0, 0.0};
    if (gb_state.count > 0U) {
        gb_output.variance_rad_s2 = (adcs_vec3_t){
            gb_state.m2_rad_s2.x / (double)gb_state.count,
            gb_state.m2_rad_s2.y / (double)gb_state.count,
            gb_state.m2_rad_s2.z / (double)gb_state.count};
    } else {
        gb_output.variance_rad_s2 = (adcs_vec3_t){0.0, 0.0, 0.0};
    }
    gb_output.rejection = GB_REJECT_NONE;
} else {
    gb_output.bias_rad_s = (adcs_vec3_t){0.0, 0.0, 0.0};
    if (gb_state.mode == GB_FAULT) {
        /* 保留本周期已设置的 rejection */
    } else {
        gb_output.rejection = GB_REJECT_NONE;
        gb_output.variance_rad_s2 = (adcs_vec3_t){0.0, 0.0, 0.0};
        gb_output.rejected_windows = 0U;
    }
}
